package session

import "github.com/sloprail/harness-mocks/internal/transcript"

// Phase is a point in a session's life at which a harness fires a hook.
type Phase int

const (
	// Start is the beginning of a session.
	Start Phase = iota
	// End is the end of a session.
	End
)

// NoConversationError is a resume naming a session that has no transcript.
type NoConversationError struct {
	SessionID string
	// Fire is the phases whose hooks still fire when the resume fails: the end
	// of the session, and never its start.
	Fire []Phase
}

func (e *NoConversationError) Error() string { return "no conversation with session " + e.SessionID }

// Resumed is a session continued from its transcript.
type Resumed struct {
	// Path is the existing transcript, where the session's records go, wherever
	// it was begun.
	Path string
	// Reported is the transcript path the harness reports: under the project
	// directory of the directory the session is resumed in, which holds no file
	// when the session began elsewhere.
	Reported string
}

// Resume continues session id from its existing transcript, or fails with a
// *NoConversationError when there is none.
//
// sr:capability session-resume-unknown
func Resume(l transcript.Layout, configDir, cwd, id string) (Resumed, error) {
	path := Find(l, configDir, cwd, id)
	if path == "" {
		return Resumed{}, &NoConversationError{SessionID: id, Fire: []Phase{End}}
	}
	return Resumed{Path: path, Reported: l.FilePath(configDir, cwd, id)}, nil
}
// Package session is the harness-neutral core of finding, resuming and forking
// a session's transcript.
package session

import (
	"os"
	"path/filepath"
	"strings"

	"github.com/sloprail/harness-mocks/internal/transcript"
)

// Exists reports whether p is a regular file.
func Exists(p string) bool {
	fi, err := os.Stat(p)
	return err == nil && fi.Mode().IsRegular()
}

// Find is the existing transcript of session id: under cwd's project
// directory, else in any other project directory (a session begun in another
// directory is resumed all the same); the most recently written wins when
// several hold it. It is "" when none does, and for an id that is not a plain
// file name.
//
// sr:capability session-resume
func Find(l transcript.Layout, configDir, cwd, id string) string {
	if id == "" || strings.ContainsAny(id, `/\`) || id == "." || id == ".." {
		return ""
	}
	if p := l.FilePath(configDir, cwd, id); Exists(p) {
		return p
	}
	entries, err := os.ReadDir(filepath.Join(configDir, l.ProjectsDir))
	if err != nil {
		return ""
	}
	best := ""
	var bestMod int64
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		p := filepath.Join(configDir, l.ProjectsDir, e.Name(), id+l.Ext)
		fi, err := os.Stat(p)
		if err != nil || !fi.Mode().IsRegular() {
			continue
		}
		if best == "" || fi.ModTime().UnixNano() > bestMod {
			best, bestMod = p, fi.ModTime().UnixNano()
		}
	}
	return best
}
// Package session is the rollout file a codex-mock session leaves under
// $CODEX_HOME/sessions, which a scenario script reads as it goes.
package session

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// File is a session's append-only rollout: one JSON record per line.
type File struct {
	Path string
	f    *os.File
}

// Create starts the rollout of session id at
// <home>/sessions/YYYY/MM/DD/rollout-<time>-<id>.jsonl, with its meta record.
func Create(home, id, cwd string, now time.Time) (*File, error) {
	dir := filepath.Join(home, "sessions", now.Format("2006"), now.Format("01"), now.Format("02"))
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	path := filepath.Join(dir, fmt.Sprintf("rollout-%s-%s.jsonl", now.Format("2006-01-02T15-04-05"), id))
	f, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	s := &File{Path: path, f: f}
	s.append("session_meta", map[string]any{"id": id, "session_id": id, "cwd": cwd,
		"originator": "codex_exec", "source": "exec", "cli_version": "mock"})
	return s, nil
}

func (s *File) append(kind string, payload map[string]any) {
	enc := json.NewEncoder(s.f)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(map[string]any{"timestamp": time.Now().UTC().Format(time.RFC3339Nano), "type": kind, "payload": payload})
}

func message(role, ctype, text string) map[string]any {
	return map[string]any{"type": "message", "role": role,
		"content": []map[string]string{{"type": ctype, "text": text}}}
}

// User records a user message: the prompt, or the text a hook sent in its place.
func (s *File) User(text string) { s.append("response_item", message("user", "input_text", text)) }

// Developer records context a hook added.
func (s *File) Developer(text string) {
	s.append("response_item", message("developer", "input_text", text))
}

// Assistant records a message from the agent.
func (s *File) Assistant(text string) {
	s.append("response_item", message("assistant", "output_text", text))
}

// ToolCall records a tool call the agent made.
func (s *File) ToolCall(callID, name string, input json.RawMessage) {
	s.append("response_item", map[string]any{"type": "function_call", "call_id": callID, "name": name, "arguments": string(input)})
}

// ToolOutput records what the agent was told a tool call returned.
func (s *File) ToolOutput(callID, output string) {
	s.append("response_item", map[string]any{"type": "function_call_output", "call_id": callID, "output": output})
}

// Close ends the rollout.
func (s *File) Close() error { return s.f.Close() }
// Package runner is one `codex exec` run: the session, its hooks, and the turn.
package runner

import (
	"context"
	"errors"
	"fmt"
	"io"
	"time"

	"github.com/sloprail/harness-mocks/codex-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/codex-mock/internal/events"
	"github.com/sloprail/harness-mocks/codex-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/codex-mock/internal/session"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// Config is everything a run is told, read once at the entrypoint.
type Config struct {
	// Script is the scenario script that drives the agent.
	Script string
	Prompt string
	// Cwd is the session's working directory.
	Cwd string
	// CodexHome holds the user's hooks.json and the session's rollout.
	CodexHome string
	Model     string
	// Environ is the environment the mock was started with.
	Environ []string
	// JSON prints the event stream on Stdout; otherwise Stdout gets the
	// agent's final message.
	JSON           bool
	Stdout, Stderr io.Writer
}

// state is the state of one run, shared by Codex's side of the turn and of
// its tool calls.
type state struct {
	cfg     Config
	id      string
	turnID  string
	hooks   *hooks.Invoker
	events  *events.Stream
	rollout *session.File
	toolEnv []string
}

// Run starts the session, fires SessionStart, and runs one turn.
// sr:provides session-start-hook/codex
// sr:provides session-end-hook/codex
// sr:provides noninteractive-run/codex
func Run(ctx context.Context, cfg Config) error {
	if cfg.Script == "" {
		return errors.New("codex-mock: a scenario script is required (--script or A10N_MOCK_SCRIPT)")
	}
	hookCfg, err := hooks.Load(cfg.CodexHome, cfg.Cwd)
	if err != nil {
		return fmt.Errorf("codex-mock: cannot load hooks: %w", err)
	}
	id := coresession.NewID()
	rollout, err := session.Create(cfg.CodexHome, id, cfg.Cwd, time.Now())
	if err != nil {
		return fmt.Errorf("codex-mock: cannot create the session file: %w", err)
	}
	defer rollout.Close()
	out := cfg.Stdout
	if !cfg.JSON {
		out = io.Discard
	}
	s := &state{cfg: cfg, id: id, turnID: coresession.NewID(), rollout: rollout, events: events.New(out),
		toolEnv: childenv.ToolEnv(cfg.Environ, id)}
	s.hooks = &hooks.Invoker{Config: hookCfg, Dir: cfg.Cwd, Environ: cfg.Environ, Ident: childenv.HookIdentity(),
		Common: hooks.Common{SessionID: id, TranscriptPath: rollout.Path, Cwd: cfg.Cwd, Model: cfg.Model,
			PermissionMode: "bypassPermissions"}}
	s.events.ThreadStarted(id)
	for _, o := range s.hooks.Fire(ctx, hooks.SessionStart, "startup", map[string]any{"source": "startup"}) {
		if d := hooks.Interpret(hooks.SessionStart, o); d.Context != "" {
			rollout.Developer(d.Context)
		}
	}
	s.events.TurnStarted()
	last, err := turnloop.Run(ctx, turnHost{s}, turnloop.Params{
		Script: cfg.Script, Dir: cfg.Cwd, Environ: cfg.Environ, Prompt: cfg.Prompt})
	s.events.TurnCompleted()
	// The session ends with the run, for the one reason a non-interactive run has;
	// what the hook prints is not read.
	s.hooks.Fire(ctx, hooks.SessionEnd, "other", map[string]any{"reason": "other"})
	if !cfg.JSON && last != "" {
		fmt.Fprintln(cfg.Stdout, last)
	}
	return err
}

// newID is a random identifier in the shape of a version 4 UUID.

package transcript

import (
	"bytes"
	"encoding/json"
)

// Marshal encodes a record without HTML escaping, the way a harness writes its
// transcript: a reader looking for the real text (a notification's markup, a
// hook's "a && b") must find it.
func Marshal(v any) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return nil, err
	}
	return bytes.TrimRight(buf.Bytes(), "\n"), nil
}

// Envelope is the bookkeeping a harness writes on every record: field name to
// value (session, working directory, branch, timestamp, version, how the run
// was launched, ...). What the fields are and are called is the harness's.
type Envelope map[string]any

// Stamp is line with every envelope field the record does not carry already,
// and no other change. A line that is not a JSON object is returned as it is.
//
// sr:capability transcript-record-envelope
func (e Envelope) Stamp(line []byte) []byte {
	var rec map[string]any
	if err := json.Unmarshal(line, &rec); err != nil || rec == nil {
		return line
	}
	changed := false
	for k, v := range e {
		if _, ok := rec[k]; !ok {
			rec[k] = v
			changed = true
		}
	}
	if !changed {
		return line
	}
	if b, err := Marshal(rec); err == nil {
		return b
	}
	return line
}

// MarkPrompt sets marks on a prompt record when the run is non-interactive, so
// a reader can tell a prompt handed to a scripted run from a typed one. A
// record keeps a mark it carries already.
func MarkPrompt(rec map[string]any, nonInteractive bool, marks map[string]any) {
	if !nonInteractive {
		return
	}
	for k, v := range marks {
		if _, ok := rec[k]; !ok {
			rec[k] = v
		}
	}
}

// Chain is line with a uuid (minted by newUUID when absent) and a parent link:
// fields uuidKey and parentKey are filled only where the record lacks them, the
// parent with parent, or an explicit null for the first record of a file. It
// returns the record's uuid so the caller can advance the chain. A line that is
// not a JSON object is returned unchanged with an empty uuid.
func Chain(line []byte, parent, uuidKey, parentKey string, newUUID func() string) (out []byte, uuid string) {
	var rec map[string]any
	if err := json.Unmarshal(line, &rec); err != nil || rec == nil {
		return line, ""
	}
	changed := false
	if s, ok := rec[uuidKey].(string); ok && s != "" {
		uuid = s
	} else if uuid = newUUID(); uuid != "" {
		rec[uuidKey] = uuid
		changed = true
	}
	if _, present := rec[parentKey]; !present {
		if parent != "" {
			rec[parentKey] = parent
		} else {
			rec[parentKey] = nil
		}
		changed = true
	}
	if !changed {
		return line, uuid
	}
	if b, err := Marshal(rec); err == nil {
		return b, uuid
	}
	return line, uuid
}
