// FindUnder is the existing transcript of session id for a harness that files
// transcripts by date, not by working directory: the most recently written
// file under root whose name ends in "-<id><ext>". It is "" when none does,
// and for an id that is not a plain file name.
//
// sr:capability session-resume
func FindUnder(root, ext, id string) string {
	if id == "" || strings.ContainsAny(id, `/\`) || id == "." || id == ".." {
		return ""
	}
	best := ""
	var bestMod int64
	_ = filepath.WalkDir(root, func(p string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() || !strings.HasSuffix(d.Name(), "-"+id+ext) {
			return nil
		}
		if fi, err := d.Info(); err == nil && fi.Mode().IsRegular() && (best == "" || fi.ModTime().UnixNano() > bestMod) {
			best, bestMod = p, fi.ModTime().UnixNano()
		}
		return nil
	})
	return best
}

