	for _, l := range first.hookLog() {
		ev, _ := l["hook_event_name"].(string)
		src, _ := l["source"].(string)
		gotEvents = append(gotEvents, ev+" "+src)
		assert.NotContains(t, ev, "Subagent")
		if sid, _ := l["session_id"].(string); sid != "" {
