package runner

import (
	"os"
	"strings"

	coresession "github.com/sloprail/harness-mocks/internal/session"
)

// sessionID is the id of the run's session: the one it resumes, or a new one.
// A session resumed from another workspace keeps its id (recorded:
// runs/session-resume).
//
// sr:provides session-resume/cursor
func sessionID(cfg Config) string {
	if cfg.Resume != "" {
		return cfg.Resume
	}
	return coresession.NewID()
}

// resume makes the transcript the one the session continues in: when this
// workspace holds the session's transcript already, the new messages follow its
// own, and its closing turn_ended line is not left in the middle (the file ends
// with the last turn's, recorded: runs/session-resume). A workspace the session
// was not begun in holds none, so the resumed run starts a transcript of its own
// there, without the earlier conversation. Nothing changes for a new session.
//
// sr:provides session-resume/cursor
func (t *transcript) resume() {
	b, err := os.ReadFile(t.path)
	if err != nil {
		return
	}
	lines := strings.Split(strings.TrimRight(string(b), "\n"), "\n")
	if n := len(lines); n > 0 && strings.Contains(lines[n-1], `"turn_ended"`) {
		_ = os.WriteFile(t.path, []byte(strings.Join(lines[:n-1], "\n")+"\n"), 0o644)
	}
}

